async def act(page):
    """
    Plan (step-by-step):
    1. Navigate (relative) to the Manage Products grid for Catalog.
    2. Filter by product name "Nona Fitness Tank" if a Name textbox exists, then run Search.
    3. Open the product edit page by clicking the product link.
    4. Open the "Associated Products" tab/section.
    5. For each color in ["Blue", "Purple"] attempt to create/add a simple associated product with Size = "XXS".
       - Try commonly-seen flows: click creation/add button, fill Size and Color comboboxes, set SKU if possible, set Status, then Save.
       - If a creation flow isn't available, attempt to locate an associated product row for the color and edit/fill the Size field inline and save.
    6. Save the parent configurable product.

    Note about knowledge_base: there are no helper functions exposed in the knowledge_base for this task, so all interactions are performed directly via Playwright locators.
    """
    product_name = "Nona Fitness Tank"
    colors = ["Blue", "Purple"]

    # 1) Go to Manage Products (relative goto)
    await page.goto("/index.php/admin/catalog/product/")
    await page.wait_for_timeout(1000)

    # 2) Try to filter by product name
    try:
        # Prefer an explicit Name textbox if present
        if await page.get_by_role("textbox", name="Name").count() > 0:
            await page.get_by_role("textbox", name="Name").first.fill(product_name)
        elif await page.get_by_role("textbox").count() > 0:
            # fallback to first textbox on the page
            await page.get_by_role("textbox").first.fill(product_name)
    except Exception:
        # continue even if filtering fails
        pass

    # Click a Search/Filter button if present
    try:
        if await page.get_by_role("button", name="Search").count() > 0:
            await page.get_by_role("button", name="Search").first.click()
        elif await page.get_by_role("button", name="Filter").count() > 0:
            await page.get_by_role("button", name="Filter").first.click()
        elif await page.get_by_role("button", name="Go").count() > 0:
            await page.get_by_role("button", name="Go").first.click()
    except Exception:
        pass

    await page.wait_for_timeout(1500)

    # 3) Open the product edit page by clicking the product link
    try:
        if await page.get_by_role("link", name=product_name).count() > 0:
            await page.get_by_role("link", name=product_name).first.click()
        else:
            # try partial match using the first word of the product name
            first_word = product_name.split()[0]
            if await page.get_by_role("link", name=first_word).count() > 0:
                await page.get_by_role("link", name=first_word).first.click()
            else:
                # As a last resort try clicking any link that contains 'Nona'
                if await page.get_by_role("link", name="Nona").count() > 0:
                    await page.get_by_role("link", name="Nona").first.click()
    except Exception:
        # If we cannot open the product, nothing else to do
        return

    # wait for the product edit page to load
    await page.wait_for_timeout(1200)

    # 4) Switch to Associated Products tab/section
    associated_opened = False
    try:
        if await page.get_by_role("tab", name="Associated Products").count() > 0:
            await page.get_by_role("tab", name="Associated Products").first.click()
            associated_opened = True
        elif await page.get_by_role("link", name="Associated Products").count() > 0:
            await page.get_by_role("link", name="Associated Products").first.click()
            associated_opened = True
    except Exception:
        pass

    await page.wait_for_timeout(800)

    # Identify a container/group that represents the Associated Products area if available
    associated_group = None
    try:
        if await page.get_by_role("group", name="Associated Products").count() > 0:
            associated_group = page.get_by_role("group", name="Associated Products").first
        elif associated_opened and await page.get_by_role("group").count() > 0:
            # fallback to first group if tab opened but no named group
            associated_group = page.get_by_role("group").first
    except Exception:
        associated_group = None

    # Helper to click a button within the associated group if available, otherwise global
    async def click_button_in_associated(name):
        try:
            if associated_group is not None and await associated_group.get_by_role("button", name=name).count() > 0:
                await associated_group.get_by_role("button", name=name).first.click()
                return True
            if await page.get_by_role("button", name=name).count() > 0:
                await page.get_by_role("button", name=name).first.click()
                return True
        except Exception:
            return False
        return False

    # 5) For each color, try to create associated simple product with Size=XXS
    for color in colors:
        created = False
        # Try common create/add flows inside associated products
        try:
            for btn_name in ["Create Product", "Add New", "Add", "Add Product", "New Product"]:
                ok = await click_button_in_associated(btn_name)
                if ok:
                    created = True
                    break
        except Exception:
            created = False

        # If creation form/modal opened, try to fill fields
        if created:
            await page.wait_for_timeout(800)
            try:
                # Size
                try:
                    if await page.get_by_role("combobox", name="Size").count() > 0:
                        await page.get_by_role("combobox", name="Size").first.select_option(label="XXS")
                    elif await page.get_by_role("combobox").count() > 0:
                        await page.get_by_role("combobox").first.select_option(label="XXS")
                except Exception:
                    pass

                # Color
                try:
                    if await page.get_by_role("combobox", name="Color").count() > 0:
                        await page.get_by_role("combobox", name="Color").first.select_option(label=color)
                    elif await page.get_by_role("combobox").count() > 1:
                        await page.get_by_role("combobox").nth(1).select_option(label=color)
                except Exception:
                    pass

                # SKU: if a SKU textbox exists and is empty, fill a generated SKU
                try:
                    if await page.get_by_role("textbox", name="SKU").count() > 0:
                        sku_box = page.get_by_role("textbox", name="SKU").first
                        current = await sku_box.input_value()
                        if not current:
                            generated = f"nona-fitness-tank-{color.lower()}-xxs"
                            await sku_box.fill(generated)
                except Exception:
                    pass

                # Status to Enabled if present
                try:
                    if await page.get_by_role("combobox", name="Status").count() > 0:
                        await page.get_by_role("combobox", name="Status").first.select_option(label="Enabled")
                except Exception:
                    pass

                # Click Save within creation form (prefer within associated_group if present)
                try:
                    saved = False
                    if associated_group is not None and await associated_group.get_by_role("button", name="Save").count() > 0:
                        await associated_group.get_by_role("button", name="Save").first.click()
                        saved = True
                    elif await page.get_by_role("button", name="Save").count() > 0:
                        await page.get_by_role("button", name="Save").first.click()
                        saved = True
                    if saved:
                        await page.wait_for_timeout(1000)
                except Exception:
                    pass

            except Exception:
                pass
        else:
            # If there is no creation flow available, attempt to edit an existing associated product row to add size value
            try:
                if await page.get_by_role("row", name=color).count() > 0:
                    row = page.get_by_role("row", name=color).first
                    if await row.get_by_role("textbox", name="Size").count() > 0:
                        await row.get_by_role("textbox", name="Size").first.fill("XXS")
                        if await row.get_by_role("button", name="Save").count() > 0:
                            await row.get_by_role("button", name="Save").first.click()
                            await page.wait_for_timeout(500)
            except Exception:
                pass

    # 6) Save the parent product (top-level Save)
    try:
        if await page.get_by_role("button", name="Save").count() > 0:
            # click the first Save (main Save)
            await page.get_by_role("button", name="Save").first.click()
            await page.wait_for_timeout(1200)
    except Exception:
        pass

